mapper.select:
SELECT da.id, da.device_id, d.device_no, d.device_name, da.alarm_type, da.alarm_status, da.occurred_at, da.recovered_at FROM device_alarm AS da INNER JOIN device AS d ON d.id = da.device_id WHERE 1 = 1
AND d.device_no LIKE CONCAT('%', #{deviceNo}, '%')
AND d.device_name LIKE CONCAT('%', #{deviceName}, '%')
AND da.alarm_type = #{alarmType}
AND da.alarm_status = #{alarmStatus}
AND da.occurred_at >= #{occurredAtStart}
AND da.occurred_at <= #{occurredAtEnd}
ORDER BY da.occurred_at DESC, da.id DESC
